import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Button, Card, Descriptions, Flex, Space, Tag, Typography, message } from 'antd';
import { apiRequest } from '../api';
import { usePermissions } from '../hooks/usePermissions';

const { Title, Text } = Typography;

type BotStatus = {
  active: boolean;
  pid?: number;
  updated_at?: string;
};

const STATUS_ENDPOINT = '/admin/bot/status';
const START_ENDPOINT = '/admin/bot/start';
const STOP_ENDPOINT = '/admin/bot/stop';

const StatusTag: React.FC<{ active: boolean }> = ({ active }) => (
  <Tag color={active ? 'green' : 'red'}>{active ? 'active' : 'inactive'}</Tag>
);

const BotControl: React.FC = () => {
  const { state } = usePermissions();
  const isArchitect = useMemo(() => state.roles.some(r => r.name === 'architect'), [state.roles]);

  const [status, setStatus] = useState<BotStatus | null>(null);
  const [loading, setLoading] = useState(false);
  const [starting, setStarting] = useState(false);
  const [stopping, setStopping] = useState(false);

  const loadStatus = useCallback(async () => {
    try {
      setLoading(true);
      const data = await apiRequest(STATUS_ENDPOINT, 'GET');
      setStatus({ active: !!data?.active, pid: data?.pid, updated_at: data?.updated_at });
    } catch (e: any) {
      console.error('Failed to load bot status', e);
      message.error('Не удалось получить статус бота');
    } finally {
      setLoading(false);
    }
  }, []);

  const handleStart = useCallback(async () => {
    try {
      setStarting(true);
      await apiRequest(START_ENDPOINT, 'POST');
      message.success('Бот запускается');
      setTimeout(loadStatus, 800);
    } catch (e: any) {
      console.error('Failed to start bot', e);
      message.error('Не удалось запустить бота');
    } finally {
      setStarting(false);
    }
  }, [loadStatus]);

  const handleStop = useCallback(async () => {
    try {
      setStopping(true);
      await apiRequest(STOP_ENDPOINT, 'POST');
      message.success('Бот останавливается');
      setTimeout(loadStatus, 800);
    } catch (e: any) {
      console.error('Failed to stop bot', e);
      message.error('Не удалось остановить бота');
    } finally {
      setStopping(false);
    }
  }, [loadStatus]);

  useEffect(() => { loadStatus(); }, [loadStatus]);

  return (
    <Flex vertical gap={16} style={{ padding: 'var(--sp-spacing-sm)', boxSizing: 'border-box', maxWidth: '100%' }}>
      <Title level={3} style={{ margin: 0 }}>Управление ботом</Title>
      {!isArchitect && (
        <Text type="danger">Недостаточно прав. Доступно только для роли architect.</Text>
      )}

      <Card loading={loading}>
        <Flex align="center" justify="space-between" wrap>
          <Space size="middle" align="center">
            <Text strong>Статус:</Text>
            <StatusTag active={!!status?.active} />
          </Space>
          <Space>
            <Button onClick={loadStatus}>Обновить</Button>
            <Button type="primary" onClick={handleStart} disabled={!isArchitect || !!status?.active} loading={starting}>Запустить</Button>
            <Button danger onClick={handleStop} disabled={!isArchitect || !status?.active} loading={stopping}>Остановить</Button>
          </Space>
        </Flex>

        <Descriptions size="small" column={1} style={{ marginTop: 'var(--sp-spacing-sm)' }}>
          <Descriptions.Item label="PID">{status?.pid ?? '-'}</Descriptions.Item>
          <Descriptions.Item label="Обновлено">{status?.updated_at ?? '-'}</Descriptions.Item>
        </Descriptions>
      </Card>
    </Flex>
  );
};

export default BotControl;


